contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient balance");

        (uint unlockBefore, uint balBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;
        uint minSum = c.MinSum(); if (__ESBMC_reverted()) return;

        c.Put{value: amount}(0); if (__ESBMC_reverted()) return;

        (uint unlockAfter, uint balAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        // General invariants for Put:
        // 1. It must not revert (caller has enough balance and min sum not needed for Put)
        // 2. Holder balance must increase by exactly the sent amount, or remain unchanged if overflow prevented it? 
        // In Solidity 0.8.0 overflow reverts, so since require passes no revert should occur.
        // 3. Contract balance must increase by exactly the sent amount.
        // We observe c.MinSum to ensure initialized or not, but Put works regardless.
        assert(balAfter >= balBefore && cBalBefore + amount == address(c).balance);
    }

    receive() external payable {}
}

