import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint256 unlockBefore;
        uint256 balBefore;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockBefore = __r0; balBefore = __r1; } catch { return; }
        uint cBalBefore = address(c).balance;
        uint256 minSum;
        try c.MinSum() returns (uint256 __r) { minSum = __r; } catch { return; }
        try c.Put{value: amount}(0) {} catch { return; }
        uint256 unlockAfter;
        uint256 balAfter;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockAfter = __r0; balAfter = __r1; } catch { return; }
        assertTrue(balAfter >= balBefore && cBalBefore + amount == address(c).balance);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
